import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-reset-password',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './reset-password.component.html',
  styleUrls: ['./reset-password.component.scss']
})
export class ResetPasswordComponent {
  form: FormGroup;
  token = '';
  isLoading = false;
  hasError = false;
  successMessage = '';
  errorMessage = '';

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private authService: AuthService
  ) {
    this.form = this.fb.group({
      newPassword: ['', [Validators.required, Validators.minLength(8)]],
      confirmPassword: ['', [Validators.required]]
    }, { validators: this.passwordMatchValidator });

    this.token = this.route.snapshot.queryParamMap.get('token') ?? '';
  }

  get newPassword() { return this.form.get('newPassword'); }
  get confirmPassword() { return this.form.get('confirmPassword'); }

  private passwordMatchValidator(form: FormGroup): { [key: string]: boolean } | null {
    const p1 = form.get('newPassword')?.value;
    const p2 = form.get('confirmPassword')?.value;
    return p1 === p2 ? null : { passwordMismatch: true };
  }

  submit(): void {
    if (!this.token) {
      this.hasError = true;
      this.errorMessage = 'Token ausente na URL.';
      return;
    }

    if (this.form.invalid || this.isLoading) {
      return;
    }

    this.isLoading = true;
    this.hasError = false;
    this.errorMessage = '';

    this.authService.resetPassword(this.token, this.form.value.newPassword as string).subscribe({
      next: (response) => {
        this.successMessage = response.message;
        this.isLoading = false;
      },
      error: (error) => {
        this.hasError = true;
        this.errorMessage = error?.error?.message || 'Falha ao redefinir senha.';
        this.isLoading = false;
      }
    });
  }

  goToLogin(): void {
    this.router.navigate(['/login']);
  }
}
<div class="reset-container">
  <div class="reset-card">
    <h1>Redefinir senha</h1>
    <p>Defina uma nova senha para sua conta.</p>

    <form [formGroup]="form" (ngSubmit)="submit()" class="reset-form">
      <label for="newPassword">Nova senha</label>
      <input id="newPassword" type="password" formControlName="newPassword" [class.error]="newPassword?.invalid && newPassword?.touched" />
      <small class="error" *ngIf="newPassword?.errors?.['required'] && newPassword?.touched">Senha obrigatoria.</small>
      <small class="error" *ngIf="newPassword?.errors?.['minlength'] && newPassword?.touched">Minimo 8 caracteres.</small>

      <label for="confirmPassword">Confirmar senha</label>
      <input id="confirmPassword" type="password" formControlName="confirmPassword" [class.error]="confirmPassword?.invalid && confirmPassword?.touched" />
      <small class="error" *ngIf="confirmPassword?.errors?.['required'] && confirmPassword?.touched">Confirmacao obrigatoria.</small>
      <small class="error" *ngIf="form.errors?.['passwordMismatch'] && confirmPassword?.touched">As senhas nao coincidem.</small>

      <div class="alert success" *ngIf="successMessage">{{ successMessage }}</div>
      <div class="alert error" *ngIf="hasError">{{ errorMessage }}</div>

      <button type="submit" [disabled]="isLoading || form.invalid">
        <span *ngIf="!isLoading">Atualizar senha</span>
        <span *ngIf="isLoading">Atualizando...</span>
      </button>
    </form>

    <a href="javascript:void(0)" (click)="goToLogin()">Voltar para login</a>
  </div>
</div>
